import{z as s,x as d,o as l,c as h,q as i,j as E,D as r,d as t,s as n,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"高 NA 下标量近似失效","description":"","frontmatter":{"title":"高 NA 下标量近似失效","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/scalar-breakdown-high-na.md","filePath":"litho/scalar-breakdown-high-na.md","lastUpdated":1791063341000}'),p={name:"litho/scalar-breakdown-high-na.md"};function m(B,a,N,c,f,F){const o=d("Mermaid");return l(),h("div",null,[a[2]||(a[2]=i('<h1 id="高-na-下标量近似失效" tabindex="-1">高 NA 下标量近似失效 <a class="header-anchor" href="#高-na-下标量近似失效" aria-label="Permalink to &quot;高 NA 下标量近似失效&quot;">​</a></h1><div class="epigraph"><p>傅里叶骨架假定一个标量 $U$ 与一只光瞳；孔径角一大，电场的纵向分量不能再丢，模方也不再等于胶里的能量。</p><footer>—— 电磁边值见 Born &amp; Wolf；高 NA 光刻的标量失效对照 Mack / Flagello</footer></div><p><a href="/litho/speckle">上一课</a>把过强空间相干的随机纹理收掉。至此补层的标量骨架——对、采样、PSF、CTF/OTF、TCC/SOCS——已经齐。缺口是：<strong>这副骨架何时不能当最终强度用</strong>。主干已有<a href="/litho/vector-imaging">矢量成像</a>与 <a href="/litho/te-tm-polarization">TE/TM</a>；本课只标失效判据，不重写 Jones 通道。浸没把夹角再做大，留给<a href="/litho/immersion-vector-imaging">下一课</a>。不重推 \\(k_1\\lambda/\\mathrm{NA}\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标量傅里叶光学：亥姆霍兹标量解、光瞳乘法、像面 \\(I\\propto|U|^2\\)。推导暗用：偏振与传播方向解耦、光线与光轴夹角足够小、界面上 s/p 差可忽略。当 \\(\\mathrm{NA}\\gtrsim 0.7\\)，边缘光线的 \\(E_z\\) 不可忽略；TM 一对衍射级的 \\(\\mathbf{E}_1\\cdot\\mathbf{E}_2^*\\) 随 \\(2\\theta\\) 下降。标量对比、标量 NILS、标量 Airy 都偏乐观。</p><p><span class="marginnote">术语翻译：「标量」模型把光当成一个只带大小的数，方向和偏振都忽略；「矢量」模型记住电场是有方向的箭头。箭头一歪，两束光相加就不再是简单的大小相加，干涉对比随之改变。</span></p><p>缺口不是再从麦克斯韦方程讲起，而是给已经写过的卷积一个<strong>适用范围</strong>：低 NA、松节距、不谈偏振的层，骨架继续当计算核；密线、浸没、High-NA EUV，骨架只保留「频率仍由光瞳切」，强度改成能量沉积。</p><h3 id="失效不是截止变了" tabindex="-1">失效不是截止变了 <a class="header-anchor" href="#失效不是截止变了" aria-label="Permalink to &quot;失效不是截止变了&quot;">​</a></h3><p>相干截止仍是光瞳边缘对应的空间频率，采样 Nyquist 仍按那条截止来。变的是 \\(H\\) 从标量 \\(P\\) 换成矢量传递，PSF 从一只 jinc 换成偏振相关的能量核。把「标量不够」理解成「要改 \\(\\mathrm{NA}\\) 定义」会去拧瑞利式，而不是去换成像模型。</p><p><span class="marginnote">干式 ArF \\(\\mathrm{NA}=0.93\\) 已经要小心；浸没 1.35 必须默认矢量。孔和二维图形更早付税，因为不能让两向同时走纯 TE。主干矢量课给了接口，本课只把它接到傅里叶骨架的边界上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断：同一掩模、同一 \\(S\\)，比较标量 \\(I\\) 与胶内吸收 \\(I_\\mathrm{abs}\\)。密线的对比差随 \\(\\theta\\)、偏振出现，最佳焦距就已经存在，不是离焦才有。Flagello 把分层薄膜与高 NA 一起算：Fresnel 系数让 s/p 权重再偏一次，失效比「真空里的矢量叠加」更早。</p><p><span class="marginnote">数字实例：同偏振两束光的干涉点积是 \\(\\cos 2\\theta\\)——夹角 30° 时约 0.87，60° 时只剩 0.5，90° 时归零。条纹对比按这个因子缩水，标量模型对此一无所知。</span></p><p>计算策略：SOCS 仍可用，核改成矢量 TCC 的本征函数。Abbe 法则每个源点带 Jones。不要为了「坚持标量」去把有效 \\(k_1\\) 人为加大——那是把偏振税藏进工艺因子。</p>',14)),(l(),E(A,null,{default:r(()=>[n(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SKEL%5B%22%E6%A0%87%E9%87%8F%3A%20T%C2%B7P%20%E2%86%92%20%7CU%7C%C2%B2%22%5D%20--%3E%20OK%5B%22%E4%BD%8E%20NA%20%2F%20%E6%9D%BE%E8%8A%82%E8%B7%9D%22%5D%0A%20%20SKEL%20--%3E%20FAIL%5B%22%E9%AB%98%20NA%3A%20Ez%E3%80%81TM%20%E4%BA%A4%E5%8F%89%E9%A1%B9%22%5D%0A%20%20FAIL%20--%3E%20VEC%5B%22%E7%9F%A2%E9%87%8F%20TCC%20%2F%20%E8%83%BD%E9%87%8F%E6%B2%89%E7%A7%AF%22%5D%0A%20%20VEC%20--%3E%20SAME%5B%22%E9%A2%91%E7%8E%87%E6%88%AA%E6%AD%A2%E4%BB%8D%E7%94%B1%E5%85%89%E7%9E%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h3",{id:"与薄膜课序的预告",tabindex:"-1"},[t("与薄膜课序的预告 "),e("a",{class:"header-anchor",href:"#与薄膜课序的预告","aria-label":'Permalink to "与薄膜课序的预告"'},"​")],-1)),a[4]||(a[4]=e("p",null,"胶与 BARC 的分层改变的是沿 \\(z\\) 的驻波和界面系数，即使低 NA 也存在。高 NA 把大角度塞进同一栈，角谱每一条光线的反射不同，标量薄膜也一起失效。后课薄膜干涉先从近轴 Fresnel 讲；本课只警告：高 NA 必须把薄膜和矢量绑在一起。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"标量把两束光的干涉可见度写成 1。电磁学里可见度乘的是偏振点积与介质里的能量权重。夹角增大，点积下降，暗区抬高，阈值处斜率变缓——NILS 掉，而 MTF 若仍按标量 OTF 画会撒谎。像差相位仍乘在每个矢量通道上，所以 Zernike 敏感度也要在矢量像上扫，不能在标量 Airy 上扫完当数。",-1)),(l(),E(A,null,{default:r(()=>[n(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20ANG%5B%22%E4%B8%A4%E6%9D%9F%E8%A1%8D%E5%B0%84%E7%BA%A7%E5%A4%B9%E8%A7%92%202%CE%B8%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20DOT%5B%22%E5%81%8F%E6%8C%AF%E7%82%B9%E7%A7%AF%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DOT%20--%3E%20VIS%5B%22%E5%B9%B2%E6%B6%89%E5%8F%AF%E8%A7%81%E5%BA%A6%E4%BD%8E%E4%BA%8E%201%22%5D%0A%20%20VIS%20--%3E%20DARK%5B%22%E6%9A%97%E7%BA%B9%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20DARK%20--%3E%20SLOPE%5B%22%E9%98%88%E5%80%BC%E5%A4%84%E6%96%9C%E7%8E%87%E5%8F%98%E7%BC%93%22%5D%0A%20%20SLOPE%20--%3E%20NILS%5B%22%E6%A0%87%E9%87%8F%20NILS%20%E5%81%8F%E4%B9%90%E8%A7%82%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选浸没液、不选照明偏振产品图。也不把标量模型说成「错误」：它是零阶，OPC 校准可以把一部分误差吃进胶模型，换 NA 或换偏振后校准作废。禁止引用未公开的「标量误差纳米表」。</p><p><span class="marginnote">常见误区：以为「标量失效」等于「标量模型错了要扔」。它是零阶近似，低 NA、松节距的层照样能用；真正的陷阱是换了 NA 或偏振后仍沿用旧校准，把偏振税偷偷算进胶参数里。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标量卷积骨架在大孔径角下给出偏乐观的 \\(|U|^2\\)。</li><li>光瞳截止与采样规则仍在；变的是传递核与能量定义。</li><li>失效在最佳焦距就存在，不是焦深公式的一部分。</li><li>矢量 SOCS / Abbe 是原骨架的通道升级。</li><li>下一课：浸没如何把这件失效变成默认。</li><li>出处：Born &amp; Wolf；Flagello；Mack；主干矢量成像课。</li></ul>',5))])}const D=s(p,[["render",m]]);export{C as __pageData,D as default};
